import com.example.faketagram.ui.model.UsersViewModel
import com.example.faketagram.ui.nav.Screen
import com.example.faketagram.ui.nav.UserChatRoute
import com.example.faketagram.ui.nav.UserProfileRoute

@PreviewScreenSizes
@Composable
fun FaketagramApp(
    viewModel: UsersViewModel = viewModel(),
    navController: NavHostController = rememberNavController()
) {
    val context = LocalContext.current
    val dataService = remember { DataManagementService() }
    val resourcesService = remember(context) { ResourcesService(context) }

    val backStackEntry by navController.currentBackStackEntryAsState()
    val route = backStackEntry?.destination?.route
    val isUserProfileRoute = route?.contains(UserProfileRoute::class.qualifiedName.orEmpty()) == true
    val isUserChatRoute = route?.contains(UserChatRoute::class.qualifiedName.orEmpty()) == true

    val uiState by viewModel.uiState.collectAsState()

    // Show nav bar on chat route only when user is blocked (shows blocked screen, not chat)
    val blockedChatUserId = if (isUserChatRoute) {
        try { backStackEntry?.toRoute<UserChatRoute>()?.userId } catch (_: Exception) { null }
    } else null
    val isChatRouteBlocked = blockedChatUserId != null && uiState.isUserBlocked(blockedChatUserId)

    val showNavBar = route == Screen.HOME.name ||
            route == Screen.CHAT.name ||
            route == Screen.PROFILE.name ||
            isUserProfileRoute ||
            isChatRouteBlocked

    LaunchedEffect(Unit) {
        context(resourcesService) {
            dataService.getUsersFromJson(R.raw.users)
        }
        context(dataService) {
            viewModel.init()
        }
    }

    val appContent: @Composable (Modifier) -> Unit = { modifier ->
        NavHost(
            navController = navController,
            startDestination = Screen.HOME.name,
            modifier = modifier
        ) {
            composable(route = Screen.HOME.name) {
                StartFeedScreen(
                    uiState = uiState,
                    onUserPhotoClicked = { user ->
                        navController.navigate(
                            UserProfileRoute(user.userId)
                        )
                    },
                    modifier = Modifier
                        .fillMaxSize()
                )
            }
            composable(route = Screen.CHAT.name) {
                StartChatScreen(
                    uiState = uiState,
                    onUserClick = { user ->
                        navController.navigate(
                            UserChatRoute(user.userId)
                        )
                    },
                    modifier = Modifier
                )
            }
            composable<UserProfileRoute> { backStackEntry ->
                val profileRoute: UserProfileRoute = backStackEntry.toRoute()
                val selectedUser = uiState.getUserById(profileRoute.userId)

                if (uiState.isUserBlocked(selectedUser.userId)) {
                    StartBlockedUserScreen(
                        user = selectedUser,
                        modifier = Modifier.fillMaxSize(),
                        onUnblock = { viewModel.unblockUser(it.userId) }
                    )
                } else {
                    StartUserProfileScreen(
                        user = selectedUser,
                        modifier = Modifier.fillMaxSize(),
                        onChatClick = {
                            navController.navigate(UserChatRoute(selectedUser.userId))
                        },
                        onBlockClick = { viewModel.blockUser(it.userId) }
                    )
                }
            }
            composable<UserChatRoute> { backStackEntry ->
                val chatRoute: UserChatRoute = backStackEntry.toRoute()
                val userChat = uiState.getUserById(chatRoute.userId)

                if (uiState.isUserBlocked(userChat.userId)) {
                    StartBlockedUserScreen(
                        user = userChat,
                        modifier = Modifier.fillMaxSize(),
                        onUnblock = { viewModel.unblockUser(it.userId) }
                    )
                } else {
                    StartUserChatScreen(
                        uiState = uiState,
                        userId = userChat.userId,
                        modifier = Modifier,
                        onSendMessage = { text ->
                            viewModel.sendMessage(
                                receiverUid = userChat.firebaseUid,
                                text = text,
                            )
                        },
                        onSendPhoto = { uri ->
                            viewModel.onImageSelected(
                                receiverUid = userChat.firebaseUid,
                                uri = uri
                            )
                        }
                    )
                }
            }
            composable(route = Screen.PROFILE.name) {
                StartProfileScreen(
                    onLogoutButtonClicked = {
                        viewModel.logout()
                    },
                    modifier = Modifier
                )
            }
        }
    }

    if (showNavBar) {
        Box(modifier = Modifier.fillMaxSize()) {
            // Draw the screen first and place the bar on top.
            appContent(Modifier.fillMaxSize())

            Box(
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .imePadding()
            ) {
                EditableBottomBar(
                    selectedRoute = route,
                    profileImageRes = uiState.getCurrentUserProfilePicture()
                        ?: R.drawable.default_user,
                    onScreenSelected = { screen ->
                        navController.navigate(screen.name) {
                            launchSingleTop = true
                            restoreState = true
                            popUpTo(navController.graph.startDestinationId) {
                                saveState = true
                            }
                        }
                    }
                )
            }
        }
    } else {
        appContent(Modifier.fillMaxSize())
    }
}

@Composable
private fun EditableBottomBar(
    selectedRoute: String?,
    profileImageRes: Int,
    onScreenSelected: (Screen) -> Unit
) {
    NavigationBar(
        containerColor = Color.White.copy(alpha = 0.6f),
        modifier = Modifier
            .height(90.dp)
            .padding(0.dp)
    ) {
        Screen.entries.forEach { screen ->
            NavigationBarItem(
                selected = selectedRoute == screen.name,
                onClick = { onScreenSelected(screen) },
                icon = {
                    if (screen == Screen.PROFILE) {
                        Image(
                            painter = painterResource(profileImageRes),
                            contentDescription = "User photo",
                            modifier = Modifier
                                .clip(CircleShape)
                                .requiredSize(28.dp)
                                .border(
                                    width = 2.dp,
                                    color = MaterialTheme.colorScheme.secondary,
                                    shape = CircleShape
                                ),
                            contentScale = ContentScale.Crop
                        )
                    } else {
                        Icon(
                            imageVector = screen.icon,
                            contentDescription = screen.label,
                            tint = MaterialTheme.colorScheme.secondary
                        )
                    }
                }
            )
        }
    }
}

package com.example.faketagram.data

import com.example.faketagram.data.model.Message
import com.example.faketagram.data.model.User

data class UsersUiState(
    val users: List<User>,
    val messages: List<Message> = emptyList(),
    val authenticatedUserUid: String = "",
    val isLoading: Boolean = false,
    val error: String? = null,
) {

    fun getAuthenticatedUser(): User? {
        return users.find { it.firebaseUid == authenticatedUserUid }
    }

    fun getUsersExceptCurrent(): List<User> {
        return users.filter { it.firebaseUid != authenticatedUserUid }
    }

    fun getCurrentUserProfilePicture(): Int? {
        val currentUser = users.find { it.firebaseUid == authenticatedUserUid }
        return currentUser?.resId
    }

    fun getUserById(userId: Int): User {
        val user = users.find { it.userId == userId }
        if (user == null) {
            return User(
                userId = 0,
                username = "Unexistent user",
                age = 0,
                distance = 0.0,
                bio = "this user does not exist",
                resName = "wenaso_1",
            )
        }
        return user
    }

    fun getUserByFirebaseUid(firebaseUid: String): User {
        val user = users.find { it.firebaseUid == firebaseUid }
        if (user == null) {
            return User(
                userId = 0,
                username = "Unexistent user",
                age = 0,
                distance = 0.0,
                bio = "this user does not exist",
                resName = "wenaso_1",
            )
        }
        return user
    }

    fun getIncomingMessagesForCurrentUser(senderId: String): List<Message> {
        val otherUid = users.find { it.firebaseUid == senderId }?.firebaseUid ?: return emptyList()
        if (authenticatedUserUid.isBlank()) return emptyList()

        val result = messages
            .filter { m ->
                (m.senderUid == authenticatedUserUid && m.receiverUid == otherUid) ||
                        (m.senderUid == otherUid && m.receiverUid == authenticatedUserUid)
            }
            .sortedByDescending { it.timestamp }

        if (result.isEmpty()) {
            val defaultList: List<Message> = listOf(
                Message(
                    text = "Que casualidad, yo también soy un mensaje de prueba!",
                    senderUid = authenticatedUserUid,
                    receiverUid = otherUid,
                    timestamp = System.currentTimeMillis()
                ),
                Message(
                    text = "Hola soy un mensaje de prueba",
                    senderUid = otherUid,
                    receiverUid = authenticatedUserUid,
                    timestamp = System.currentTimeMillis()
                )
            )
            return defaultList
        } else {
            return result
        }
    }
}

