@Composable
fun StartUserProfileScreen(
    user: User,
    modifier: Modifier = Modifier,
    onChatClick: (User) -> Unit,
) {
    val photos = buildList {
        add(user.resId)
        addAll(user.galleryResIds)
    }.distinct().filter { it != 0 }

    Scaffold(
        modifier = modifier.fillMaxSize(),
        topBar = {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(110.dp)
                    .background(
                        Color.Transparent
                    )
                    .padding(top = 25.dp)
            ) {
                Image(
                    painter = painterResource(id = R.drawable.meelt_logo),
                    contentDescription = "User photo",
                    modifier = Modifier
                        .fillMaxSize()
                        .align(Alignment.BottomCenter),
                )
            }
        }
    ) { innerPadding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            contentPadding = PaddingValues(
                start = 20.dp,
                top = 20.dp,
                end = 20.dp,
                bottom = 130.dp
            )
        ) {
            itemsIndexed(photos) { index, photoResId ->
                ProfilePhotoCard(
                    photoResId = photoResId,
                    overlay = {
                        when {
                            index == 0 -> MainProfileOverlay(user = user)
                            index == 1 -> AboutMeOverlay(bio = user.bio)
                        }

                        if (index == photos.lastIndex) {
                            BottomActionsOverlay(onChatClick = { onChatClick(user) })
                        }
                    }
                )
            }
        }
    }
}

@Composable
