    }

    fun logout() {
        Firebase.auth.signOut()
    }

    fun blockUser(userId: Int) {
        _uiState.update { state ->
            state.copy(
                users = state.users.map { user ->
                    if (user.userId == userId) user.copy(isBlocked = true) else user
                }
            )
        }
    }

    fun unblockUser(userId: Int) {
        _uiState.update { state ->
            state.copy(
